-inspector dl{display:grid;grid-template-columns:80px 1fr;gap:10px;font-size:11px}.native-runtime-inspector dt{color:var(--ks-text-secondary)}.native-runtime-inspector dd{margin:0;overflow-wrap:anywhere}.native-runtime-inspector pre{max-height:220px;overflow:auto;white-space:pre-wrap;font:11px/1.6 monospace;padding:10px;background:var(--ks-bg-base)}.native-section-title{display:flex;gap:12px;align-items:center;padding:14px 18px;font-size:10px;color:var(--ks-text-secondary);letter-spacing:.06em}.native-section-title>button{margin-left:auto}.native-gantt{padding:0 18px 18px;min-width:550px}.native-gantt-header,.native-gantt-row{display:grid;grid-template-columns:190px minmax(160px,1fr) 100px;gap:16px;align-items:center;width:100%;text-align:left}.native-gantt-header{height:36px;color:var(--ks-text-secondary);font-size:10px}.native-gantt-row{min-height:56px;border-block-start:1px solid var(--ks-border-default);padding:8px 0;background:transparent}.native-gantt-row.selected{background:var(--ks-bg-tag-inactive)}.native-gantt-row small{display:block;font-size:10px;color:var(--ks-text-secondary);margin-top:4px}.native-gantt-track{height:24px;position:relative;border-inline:1px solid var(--ks-border-default);background:repeating-linear-gradient(90deg,transparent,transparent 24%,var(--ks-border-default) 25%,transparent 26%)}.native-gantt-track i{position:absolute;top:4px;height:16px;background:var(--ks-text-link);border-radius:3px}.native-gantt-track i.success{background:#42a894}.native-gantt-track i.failed,.native-gantt-track i.killed{background:#d26079}.native-attempt{border:1px solid var(--ks-border-default);padding:10px;margin:8px 0;font-size:11px;display:flex;gap:10px;flex-wrap:wrap}.native-attempt time{font-size:10px;color:var(--ks-text-secondary)}.native-target-matrix{padding:16px;display:grid;grid-template-columns:repeat(auto-fill,minmax(165px,1fr));gap:10px}.native-target{padding:12px;text-align:left;border:1px solid var(--ks-border-default);border-radius:5px;border-left:3px solid var(--ks-text-secondary);background:var(--ks-bg-base)}.native-target b,.native-target small,.native-target span{display:block;font-size:11px}.native-target span{margin:8px 0}.native-target small{color:var(--ks-text-secondary);font-size:10px}.native-target.success{border-left-color:#42a894}.native-target.failed{border-left-color:#d26079}.native-target.selected{outline:1px solid var(--ks-text-link)}.native-filters{padding:12px 18px;border-bottom:1px solid var(--ks-border-default)}.native-filters>.kel-input{max-width:320px}.native-execution select{padding:6px;border:1px solid var(--ks-border-default);border-radius:4px;background:var(--ks-bg-input);color:var(--ks-text-primary);font:11px inherit}.native-log-stream{height:520px;overflow:auto;background:var(--ks-bg-base);padding:10px 16px}.native-log-line{display:grid;grid-template-columns:160px 55px 1fr;gap:12px;padding:9px 0;border-bottom:1px solid var(--ks-border-default);font-size:11px}.native-log-line time,.native-log-line small{color:var(--ks-text-secondary);font-size:10px}.native-log-line small,.native-log-line code{display:block}.native-log-line code{white-space:pre-wrap;overflow-wrap:anywhere;margin-top:5px}.native-log-line .error,.native-error{color:#e57b94}.native-empty{padding:70px 20px;text-align:center;color:var(--ks-text-secondary)}.native-error{padding:12px 18px}.native-relation{display:flex;gap:20px;padding:16px 20px;border-bottom:1px solid var(--ks-border-default)}.native-relation>button{color:var(--ks-text-link)}.native-device-output{padding:16px}.native-device-output pre{white-space:pre-wrap;max-height:200px;overflow:auto}@media(max-width:1100px){.native-runtime-workspace,.native-target-workspace{grid-template-columns:minmax(0,1fr) 245px}.native-execution-heading{align-items:flex-start}.native-context-tabs{gap:14px}.native-execution-actions{max-width:380px}}
